using System;
using System.Collections.Generic;
using Nino.Core;

// Classes whose generated body is flat (#355, the generator seam: raw members, bools and strings through Nino.Core's
// flat kernels), and twins of them that are not (their members auto-properties): positional, as flat bodies need.
// Generated by the Roslyn 4.3 build, as in Unity. FlatTests compares the two.
namespace Nino.UnitTests.Subset.Flat
{
    public enum FlatKind : byte { None, Small, Large }

    /// <summary>
    /// A flat class that is not sealed (#355): one string after primitives declared largest first, which CoreCLR lays
    /// out as the wire does (one block of 21 bytes); a subtype leaves the run.
    /// </summary>
    [NinoType]
    public class FlatOne
    {
        public long Stamp;
        public double Score;
        public int Id;
        public FlatKind Kind;
        public string Name;
    }

    [NinoType]
    public class FlatOneDerived : FlatOne
    {
        public int Extra;
    }

    /// <summary>
    /// A flat class that is not sealed and has no subtype: its runs are written by the typed kernels (a base with
    /// subtypes, <see cref="FlatOne"/>, writes them through its dispatch loop and reads them through the kernels).
    /// </summary>
    [NinoType]
    public class FlatLeaf
    {
        public int Id;
        public string Name;
    }

    /// <summary><see cref="FlatOne"/>'s members as auto-properties: the same body, not flat (the generated body).</summary>
    [NinoType]
    public class FlatOneProps
    {
        public long Stamp { get; set; }
        public double Score { get; set; }
        public int Id { get; set; }
        public FlatKind Kind { get; set; }
        public string Name { get; set; }
    }

    /// <summary>A sealed flat class: several strings (one UTF-8) between a primitive, a struct and a bool.</summary>
    [NinoType]
    public sealed class FlatMany
    {
        public int Id;
        public string Name;
        [NinoUtf8] public string Tag;
        public DateTime At;
        public bool Flag;
        public string Text;
        public decimal Price;
    }

    /// <summary><see cref="FlatMany"/> as auto-properties: not flat, the same bytes.</summary>
    [NinoType]
    public sealed class FlatManyProps
    {
        public int Id { get; set; }
        public string Name { get; set; }
        [NinoUtf8] public string Tag { get; set; }
        public DateTime At { get; set; }
        public bool Flag { get; set; }
        public string Text { get; set; }
        public decimal Price { get; set; }
    }

    /// <summary>A flat class holding flat classes and lists of them (members and runs through one parent).</summary>
    [NinoType]
    public sealed class FlatHolder
    {
        public FlatMany One;
        public List<FlatMany> Many;
        public FlatOne[] Ones;
    }

    /// <summary>
    /// A chain of nodes each holding a run of flat classes: past NinoDepth.Inline the runs go element by element, as
    /// deferred bodies (#355).
    /// </summary>
    [NinoType]
    public sealed class FlatNode
    {
        public FlatMany[] Items;
        public FlatNode Next;
    }

    /// <summary><see cref="FlatNode"/> over <see cref="FlatManyProps"/>: the same bytes through generated bodies.</summary>
    [NinoType]
    public sealed class FlatNodeProps
    {
        public FlatManyProps[] Items;
        public FlatNodeProps Next;
    }
}
